41	// Layout: padding(8) + icon(14) + gap(8) + label + gap(8) + typeChip + padding(8)
42	// label: 14px bold ≈ 9.5px per char
43	// typeChip: 12px regular ≈ 7.5px per char + 4px left + 4px right internal padding
44	export const computeNodeWidth = (label: string, type: string): number => {
45	  const labelWidth = label.length * 9.5;
46	  const typeChipWidth = type.length * 7.5 + 8;
47	  const approxWidth = 8 + 14 + 8 + labelWidth + 8 + typeChipWidth + 8;
48	
49	  return Math.min(
50	    MAX_NODE_WIDTH,
51	    Math.max(MIN_NODE_WIDTH, Math.ceil(approxWidth))
52	  );
53	};
