70	export const getColorSetForType = (
71	  type: string
72	): { main: string; light: string } => {
73	  let hash = 0;
74	  for (let i = 0; i < type.length; i++) {
75	    hash = (hash * 31 + (type.codePointAt(i) ?? 0)) >>> 0;
76	  }
77	
78	  return COLOR_SETS[hash % COLOR_SETS.length];
79	};
