81	const ELK_KG_LAYOUT_OPTIONS = {
82	  'elk.algorithm': 'layered',
83	  'elk.direction': 'LEFT',
84	  'elk.spacing.nodeNode': '60',
85	  'elk.layered.spacing.nodeNodeBetweenLayers': '20',
86	  'elk.layered.nodePlacement.strategy': 'SIMPLE',
87	  'elk.spacing.edgeNode': '10',
88	  'elk.spacing.edgeEdge': '10',
89	  'elk.partitioning.activate': 'true',
90	};
